mapper.update:
UPDATE usage_logs
SET billing_status = #{billingStatus},
    billing_error = #{billingError}
WHERE id = #{id}

mapper.select:
SELECT * FROM usage_logs
WHERE billing_status = #{billingStatus}
  AND created_at < #{cutoff}
ORDER BY created_at ASC
LIMIT #{limit}

SELECT * FROM usage_logs
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT * FROM usage_logs
WHERE api_key_id = #{apiKeyId}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT * FROM usage_logs
WHERE account_id = #{accountId}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT * FROM usage_logs
WHERE user_id = #{userId}

    AND created_at >= #{start}


    AND created_at < #{end}

ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM usage_logs
WHERE user_id = #{userId}

    AND created_at >= #{start}


    AND created_at < #{end}

SELECT u.id AS user_id, u.username, u.email, COALESCE(SUM(ul.total_cost), 0) AS total_cost, COALESCE(SUM( ul.input_tokens + ul.output_tokens + CASE WHEN COALESCE(ul.cache_creation_5m_tokens, 0) > 0 OR COALESCE(ul.cache_creation_1h_tokens, 0) > 0 THEN COALESCE(ul.cache_creation_5m_tokens, 0) + COALESCE(ul.cache_creation_1h_tokens, 0) ELSE COALESCE(ul.cache_creation_tokens, 0) END + COALESCE(ul.cache_read_tokens, 0) ), 0) AS total_tokens, COUNT(ul.id) AS call_count FROM users u LEFT JOIN usage_logs ul ON u.id = ul.user_id AND ul.created_at >= #{start} AND ul.created_at < #{end} WHERE u.deleted_at IS NULL GROUP BY u.id, u.username, u.email HAVING COUNT(ul.id) > 0 ORDER BY
total_tokens total_cost
${sortDir}

SELECT COALESCE(AVG(duration_ms), 0) FROM usage_logs
WHERE created_at >= #{start} AND created_at < #{end}
  AND duration_ms IS NOT NULL

SELECT COUNT(*) FROM usage_logs
WHERE user_id = #{userId}
  AND created_at >= #{start} AND created_at < #{end}

SELECT COALESCE(AVG(duration_ms), 0) FROM usage_logs
WHERE user_id = #{userId}
  AND created_at >= #{start} AND created_at < #{end}
  AND duration_ms IS NOT NULL
